// 原Personal终局先分配battle、后分配result并落原头；纯读保该真实时序而不创建新伤因。
#include "resident/domains/military/military_injury_source.hpp"
#include "resident/model/dynamic_contract.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {int checks=0,failures=0;void check(bool v,const char* s){++checks;if(!v){++failures;std::cerr<<s<<'\n';}}}
int main(){
 CommonState seed;seed.identity.tick=5;seed.next_instance_id=40;ActorRecord a;a.id="a";seed.actors.insert(a.id,a);seed.facts.insert("personal_entry:20",{"personal_entry:20","personal_combat_entered","personal"});seed.facts.insert("battle:10",{"battle:10","personal_battle","personal"});CommonStore common(std::move(seed),std::make_shared<CommonCatalog>());MilitaryState military;PersonalState state;PersonalCatalog catalog;catalog.enabled=true;PersonalObjective objective;objective.id="spar";objective.injury_on_defeat=1;catalog.objectives.insert(objective.id,objective);
 PersonalBattle b;b.id="battle:10";b.phase="closed";b.applied=true;b.result_id="result:30";b.completed_tick=5;b.objective_id=objective.id;PersonalUnit u;u.actor_id="a";u.hp=0;b.units.insert(u.actor_id,u);state.battles.insert(b.id,b);PersonalFact fact;fact.battle_id=b.id;fact.result_id=b.result_id;fact.tick=5;fact.participants={"a"};fact.defeated={"a"};state.facts.insert(b.id,fact);
 auto read=[&]{return query_military_actor_injury_causes(common,military,state,catalog,"a");};auto result=read();check(result.ok&&result.value.size()==1&&result.value[0].exact_fact_id=="battle:10"&&result.value[0].completion_id=="result:30","old battle allocation retains actual later completion source");check(!common.state().facts.find("result:30")&&common.state().facts.order().front()=="personal_entry:20","completion instance is not an invented fact head");
 auto set_result=[&](const StableId& id){state.battles.find(b.id)->result_id=id;state.facts.find(b.id)->result_id=id;};set_result("result:030");check(!read().ok,"noncanonical completion allocation rejected");set_result("result:9");check(!read().ok,"completion older than battle rejected");set_result("result:40");check(!read().ok,"not yet allocated completion rejected");set_result("battle:30");check(!read().ok,"different prefix cannot impersonate result");set_result("result:30");state.facts.find(b.id)->result_id="result:31";check(!read().ok,"fact and original battle must share exact result");set_result("result:30");
 auto second=b;second.id="battle:11";state.battles.insert(second.id,second);auto duplicate=fact;duplicate.battle_id=second.id;state.facts.insert(second.id,duplicate);common.state().facts.insert(second.id,{second.id,"personal_battle","personal"});check(!read().ok,"two battles cannot borrow same completion instance");state.battles.erase(second.id);state.facts.erase(second.id);common.state().facts.erase(second.id);
 MilitaryCasualtyFact casualty;casualty.id="military:35";casualty.battle_id="military_battle:34";casualty.tick=5;casualty.actor_changes.push_back({"a","wounded",{},std::nullopt,{}, {}});military.casualty_facts.push_back(casualty);common.state().facts.insert(casualty.id,{casualty.id,"military_casualties","military"});result=read();check(result.ok&&result.value.size()==2&&result.value[1].kind=="military_wound"&&result.value[1].completion_id.empty(),"military immediate original casualty needs no completion alias");
 military.casualty_facts[0].tick=6;check(!read().ok,"stable reader still rejects future military tick");DynamicStepInput phase;phase.from_tick=5;phase.to_tick=6;check(query_military_actor_injury_causes(common,military,state,catalog,"a",phase).ok,"strict actual single phase observes military completion without changing personal source");phase.to_tick=7;check(!query_military_actor_injury_causes(common,military,state,catalog,"a",phase).ok,"wrong phase never extends observation");
 check(common.state().next_instance_id==40&&common.state().actors.find("a")->injury==0&&state.battles.find(b.id)->result_id=="result:30","query allocates and mutates nothing");
 std::cout<<"MILITARY_INJURY_COMPLETION="<<checks<<" FAILURES="<<failures<<" SCOPE=ORIGINAL_CAUSE_PURE_READ\n";return failures?1:0;
}
